$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$out="$root\M78WindowsTailResults";$base='http://192.168.122.1:8872';New-Item -ItemType Directory $out -Force|Out-Null;$name='m78-windows-tail-initial'
try{if(Test-Path "$out\$name.json"){throw 'Preserve prior tail inspection'};$paths=@("$root\M78ContinuationBuild\combined-v2\judas_engine.lib","$root\Build\Release\m78_combined-v2_concave.exe","$root\Build\Release\m78_combined-v2_runtime.exe");$files=@();foreach($p in $paths){$exists=Test-Path $p;$row=@{path=$p;exists=$exists};if($exists){$row.bytes=(Get-Item $p).Length;$row.sha256=(Get-FileHash $p).Hash.ToLower()};$files+=$row};$os=Get-CimInstance Win32_OperatingSystem;$processes=@(Get-Process|Where-Object {$_.CPU -ne $null}|ForEach-Object {@{id=$_.Id;name=$_.ProcessName;cpuSeconds=$_.CPU;workingSetBytes=$_.WorkingSet64}});@{utc=[DateTime]::UtcNow.ToString('o');freeBytes=(Get-PSDrive C).Free;freePhysicalKiB=$os.FreePhysicalMemory;freeVirtualKiB=$os.FreeVirtualMemory;files=$files;processes=$processes;scope='Read-only native tail preparation; no process/VM/source changes.'}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$name.json" -Method Post -InFile "$out\$name.json"|Out-Null}catch{$p="$out\$name-error.txt";[string]$_.Exception.Message|Set-Content $p;Invoke-WebRequest -UseBasicParsing "$base/$name-error.txt" -Method Post -InFile $p|Out-Null;exit 1}
